  setupGuardDevtest(){if(new URLSearchParams(location.search).get('devtest')!=='1')return;const n=this.save.npcs.find(x=>x.id==='van-du'),ward=this.save.npcs.find(x=>x.id==='qingyun-01'),wolf=this.beasts.find(x=>x.alive&&x.kind==='wolf');if(!n||!ward||!wolf||!n.alive||!ward.alive||activeMandate(this.save,n.id)){this.toast('Không thể tạo tình huống Hộ Đạo.');return}this.save.heaven.fragments=Math.max(100,this.save.heaven.fragments);this.save.heaven.divinePower=Math.max(100,this.save.heaven.divinePower);if(!this.save.heaven.unlocked.includes('heavenly-mandate'))unlockPower(this.save.heaven,'heavenly-mandate');for(const b of this.beasts)if(b!==wolf){b.sprite.setPosition(3450,1400);b.body.setVelocity(0,0)}n.x=1500;n.y=700;n.realmIndex=1;n.realmLevel=5;n.hp=cultivationStats(n).hpMax;n.hunger=n.fatigue=0;n.safety=100;n.goalAction='idle';n.decisionSlot=undefined;n.traits.canDam=100;n.traits.trungThanh=100;ward.x=1610;ward.y=700;ward.hp=cultivationStats(ward).hpMax;ward.safety=100;ward.hunger=0;ward.goalAction='idle';this.sprites.get(n.id)?.setPosition(n.x,n.y);this.sprites.get(ward.id)?.setPosition(ward.x,ward.y);wolf.sprite.setPosition(1680,700);wolf.hp=30;wolf.body.setVelocity(0,0);this.routes.delete(n.id);this.routes.delete(ward.id);this.selectNPC(n.id);if(!this.save.destinies?.some(r=>r.npcId===n.id))this.chooseDestinySelected();const result=this.instructProtection(ward.id);if(result.ok){this.save.clock.paused=false;this.physics.world.resume();el('pause-button').textContent='Ⅱ Tạm dừng';this.follow(n.id)}this.persist();this.toast(result.message)}
