  setupGatherDevtest(){if(new URLSearchParams(location.search).get('devtest')!=='1')return;const n=this.save.npcs.find(x=>x.id==='van-du');if(!n||!n.alive||n.ascended){this.toast('Vân Du không hợp lệ.');return}if(this.save.cultivationMandates?.some(c=>c.npcId===n.id&&['issued','accepted','active','delayed'].includes(c.status))){this.toast('Vân Du đang có chỉ dẫn.');return}for(const [index,beast] of this.beasts.entries()){beast.sprite.setPosition(3450+(index%3)*35,1400+Math.floor(index/3)*35);beast.body.setVelocity(0,0)}this.save.heaven.fragments=Math.max(100,this.save.heaven.fragments);this.save.heaven.divinePower=Math.max(100,this.save.heaven.divinePower);if(!this.save.heaven.unlocked.includes('heavenly-mandate'))unlockPower(this.save.heaven,'heavenly-mandate');n.x=1500;n.y=1000;n.hp=cultivationStats(n).hpMax;n.hunger=0;n.fatigue=0;n.safety=100;n.goalAction='work';n.decisionSlot=undefined;n.traits.canDam=100;n.traits.thamVong=80;this.sprites.get(n.id)?.setPosition(n.x,n.y);this.routes.delete(n.id);this.selectNPC(n.id);if(!this.save.destinies?.some(r=>r.npcId===n.id))this.chooseDestinySelected();const result=this.instructJourney('gather','herbs');if(result.ok){this.save.clock.paused=false;this.physics.world.resume();el('pause-button').textContent='Ⅱ Tạm dừng';this.follow(n.id)}this.persist();this.toast(result.message)}
