    details.innerHTML=`<div class="sect-member-list">${rows||'<small>Chưa có thành viên.</small>'}</div>${sect?`<small>Sư đồ: ${sect.mentors.length} · Công pháp: ${sect.ownedTechniques.join(' / ')}</small><small>Mục tiêu: ${sect.developmentGoal} · Giới hạn: ${f.memberIds.length}/${sect.memberLimit}</small><small>Nhiệm vụ: ${mission?.title??'đang chờ điều kiện'}</small>`:`<small>Địa bàn: ${f.areaId} · An toàn ${f.security}%</small>`}${conflict?`<small>${this.save.spiritVeins.find(v=>v.id===conflict.veinId)?.name}: ${conflict.status==='disputed'?'đang tranh chấp':this.save.factions.find(x=>x.id===this.save.spiritVeins.find(v=>v.id===conflict.veinId)?.ownerFactionId)?.name??'đang kiểm soát'}</small>`:''}`
